import heapq

def solution(nums, k):
    heap = []                      # min-heap of the k largest values seen so far
    for value in nums:
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:      # beats the smallest of the top k
            heapq.heapreplace(heap, value)
    return heap[0]                 # smallest of the k largest = k-th largest

