def solution(nums, k):
    # Remove the current maximum k - 1 times; the maximum left is the answer.
    # Each max() and remove() is O(n), so this is O(n * k).
    rest = list(nums)
    for _ in range(k - 1):
        rest.remove(max(rest))
    return max(rest)
